<?php foreach($depenses as$d):$name=trim(implode(' ',array_filter([$d['nom'],$d['postnom'],$d['prenom']])));$json=htmlspecialchars(json_encode($d),ENT_QUOTES,'UTF-8');$search=strtolower($d['libelle'].' '.$d['immatriculation'].' '.$name.' '.$d['categorie_nom']);?><tr data-search="<?= htmlspecialchars($search) ?>" data-category="<?= (int)$d['categorie_depense_id'] ?>" data-currency="<?= $d['devise'] ?>"><td><strong><?= date('d/m/Y',strtotime($d['date_depense'])) ?></strong><small class="expense-muted">#DEP-<?= str_pad((string)$d['id'],5,'0',STR_PAD_LEFT) ?></small></td><td><strong><?= htmlspecialchars($d['libelle']) ?></strong></td><td><div class="expense-team"><i class="bi bi-truck-front"></i><span><strong><?= htmlspecialchars($d['immatriculation']) ?></strong><small><?= htmlspecialchars($name) ?> · <?= htmlspecialchars($d['fonction_nom']) ?></small></span></div></td><td><span class="expense-category <?= $d['type_depense']==='participatif'?'participative':'' ?>"><?= htmlspecialchars($d['categorie_nom']) ?></span><small class="expense-muted"><?= $d['type_depense']==='participatif'?'Participative':'Non participative' ?></small></td><td class="expense-amount"><strong><?= number_format((float)$d['montant'],$d['devise']==='USD'?2:0,',',' ') ?> <?= $d['devise'] ?></strong></td><td><div class="row-actions"><button onclick="openExpenseModal(<?= $json ?>)"><i class="bi bi-pencil"></i></button><button class="danger" onclick="openDeleteExpense(<?= (int)$d['id'] ?>,'DEP-<?= str_pad((string)$d['id'],5,'0',STR_PAD_LEFT) ?>')"><i class="bi bi-trash3"></i></button></div></td></tr><?php endforeach;?></tbody></table></div></section></div><div id="view-categories" class="hidden"><section class="users-heading"><div><h2>Catégories de dépenses</h2><p>Classez les charges et définissez leur impact sur la rémunération.</p></div><button class="add-button" onclick="openCategoryModal()"><i class="bi bi-plus-lg"></i> Nouvelle catégorie</button></section><section class="users-toolbar"><label class="search-field"><i class="bi bi-search"></i><input id="category-search" type="search" placeholder="Rechercher une catégorie…" oninput="filterCategories()"></label><span id="category-count"><?= count($toutesCategories) ?> catégorie(s)</span></section><section class="users-table-card"><div class="users-table-scroll"><table><thead><tr><th>Catégorie</th><th>Type</th><th>Dépenses liées</th><th>Statut</th><th>Création</th><th></th></tr></thead><tbody id="categories-body"><?php foreach($toutesCategories as$c):$catJson=htmlspecialchars(json_encode($c),ENT_QUOTES,'UTF-8');?><tr data-search="<?= htmlspecialchars(strtolower($c['nom'].' '.$c['type_depense'])) ?>"><td><strong><?= htmlspecialchars($c['nom']) ?></strong></td><td><span class="expense-category <?= $c['type_depense']==='participatif'?'participative':'' ?>"><?= $c['type_depense']==='participatif'?'Participative':'Non participative' ?></span></td><td><strong><?= (int)$c['nombre_depenses'] ?></strong> dépense(s)</td><td><span class="category-status <?= $c['actif']?'active':'inactive' ?>"><?= $c['actif']?'Active':'Inactive' ?></span></td><td><?= date('d/m/Y',strtotime($c['created_at'])) ?></td><td><div class="row-actions"><button onclick="openCategoryModal(<?= $catJson ?>)"><i class="bi bi-pencil"></i></button><button class="<?= $c['actif']?'danger':'' ?>" onclick="toggleCategory(<?= (int)$c['id'] ?>,'<?= htmlspecialchars($c['nom'],ENT_QUOTES) ?>',<?= (int)$c['actif'] ?>)"><i class="bi bi-<?= $c['actif']?'pause-circle':'play-circle' ?>"></i></button></div></td></tr><?php endforeach;?></tbody></table></div></section></div></div><footer class="dashboard-footer">© <?= date('Y') ?> MWIRA Trans <span>Dépenses et catégories</span></footer></main></div>
