<div class="users-modal-overlay" id="expense-modal"><div class="users-modal expense-modal"><div class="modal-title"><div><h3 id="expense-title">Nouvelle dépense</h3><p>Charge liée à une affectation</p></div><button onclick="closeModal('expense-modal')">&times;</button></div><form method="POST" action="<?= BASE_URL ?>/depenses"><input type="hidden" name="action" id="expense-action" value="create"><input type="hidden" name="id" id="expense-id"><label>Affectation *<select name="affection_vehicule" id="expense-assignment" required><option value="">Sélectionner une affectation</option><?php foreach($affectations as$a):$n=trim(implode(' ',array_filter([$a['nom'],$a['postnom'],$a['prenom']])));?><option value="<?= (int)$a['id'] ?>"><?= htmlspecialchars($a['immatriculation'].' — '.$n.' ['.$a['matricule'].'] ('.$a['fonction_nom'].')') ?></option><?php endforeach;?></select></label><div class="expense-form-grid"><label>Catégorie *<select name="categorie_depense_id" id="categorie_depense_id" required><option value="">Sélectionner</option><?php foreach($categories as$c):?><option value="<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['nom'].' — '.($c['type_depense']==='participatif'?'Participative':'Non participative')) ?></option><?php endforeach;?></select></label><label>Date *<input type="date" name="date_depense" id="date_depense" required max="<?= date('Y-m-d') ?>"></label><label class="full-field">Libellé *<input name="libelle" id="libelle" required maxlength="255" placeholder="Ex. Carburant, réparation…"></label><label>Devise<select name="devise" id="expense-devise"><option>USD</option><option>CDF</option></select></label><label>Montant *<div class="money-input"><input type="number" name="montant" id="expense-montant" min="0.01" step="0.01" required><span id="expense-currency-label">USD</span></div></label></div><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('expense-modal')">Annuler</button><button type="submit" class="save"><i class="bi bi-check-lg"></i> Enregistrer</button></div></form></div></div>
<div class="users-modal-overlay" id="delete-expense-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-exclamation-triangle"></i></span><h3>Supprimer cette dépense ?</h3><p><strong id="delete-expense-name"></strong><br>Cette action est irréversible.</p><form method="POST" action="<?= BASE_URL ?>/depenses"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" id="delete-expense-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('delete-expense-modal')">Annuler</button><button class="delete-confirm">Supprimer</button></div></form></div></div>
