<div class="users-modal-overlay" id="toggle-category-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-toggle-on"></i></span><h3 id="toggle-category-title"></h3><p id="toggle-category-name"></p><form method="POST" action="<?= BASE_URL ?>/depenses"><input type="hidden" name="action" value="category_toggle"><input type="hidden" name="id" id="toggle-category-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('toggle-category-modal')">Annuler</button><button class="delete-confirm" id="toggle-category-button">Confirmer</button></div></form></div></div>
<link href="<?= BASE_URL ?>/assets/css/assignment-tabs.css" rel="stylesheet">
<link href="<?= BASE_URL ?>/assets/css/category-status.css" rel="stylesheet">
<script>
const expenseAssignmentData=<?= json_encode($affectations,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
function openExpenseModal(d=null){document.getElementById('expense-action').value=d?'update':'create';document.getElementById('expense-id').value=d?.id||'';const s=document.getElementById('expense-assignment');if(d&&!Array.from(s.options).some(o=>String(o.value)===String(d.affection_vehicule)))s.add(new Option(`${d.immatriculation} — ${d.nom} [${d.travailleur_matricule}]`,d.affection_vehicule));s.value=d?.affection_vehicule||'';document.getElementById('categorie_depense_id').value=d?.categorie_depense_id||'';document.getElementById('date_depense').value=d?.date_depense||'<?= date('Y-m-d') ?>';document.getElementById('libelle').value=d?.libelle||'';document.getElementById('expense-devise').value=d?.devise||'USD';document.getElementById('expense-montant').value=d?.montant||'';document.getElementById('expense-currency-label').textContent=d?.devise||'USD';document.getElementById('expense-title').textContent=d?'Modifier la dépense':'Nouvelle dépense';setupExpenseAssignmentSearch();openModal('expense-modal')}
function setupExpenseAssignmentSearch(){const s=document.getElementById('expense-assignment');let box=document.getElementById('expense-assignment-searchable');if(!box){box=document.createElement('div');box.id='expense-assignment-searchable';box.className='searchable-select';box.innerHTML='<input type="search" class="searchable-select-input" id="expense-assignment-input" placeholder="Nom ou matricule du chauffeur…" autocomplete="off"><i class="bi bi-search searchable-select-icon"></i><div class="searchable-select-results hidden" id="expense-assignment-results"></div>';s.parentNode.insertBefore(box,s);s.classList.add('native-search-select');box.querySelector('input').addEventListener('input',e=>renderExpenseAssignments(e.target.value));box.querySelector('input').addEventListener('focus',e=>renderExpenseAssignments(e.target.value))}const selected=s.options[s.selectedIndex];document.getElementById('expense-assignment-input').value=s.value&&selected?selected.text.trim():'';document.getElementById('expense-assignment-results').classList.add('hidden')}
function renderExpenseAssignments(q=''){const s=document.getElementById('expense-assignment'),r=document.getElementById('expense-assignment-results'),term=q.toLowerCase().trim(),opts=Array.from(s.options).filter(o=>o.value&&(!term||o.text.toLowerCase().includes(term)));r.innerHTML=opts.length?opts.map(o=>`<button type="button" class="searchable-option" data-id="${o.value}"><i class="bi bi-person-vcard"></i><span><strong>${escapeExpense(o.text.split('—')[1]?.trim()||o.text)}</strong><small>${escapeExpense(o.text.split('—')[0])}</small></span></button>`).join(''):'<div class="searchable-empty">Aucun chauffeur trouvé.</div>';r.classList.remove('hidden');r.querySelectorAll('button').forEach(b=>b.onclick=()=>selectExpenseAssignment(b.dataset.id))}function selectExpenseAssignment(id){const s=document.getElementById('expense-assignment');s.value=id;document.getElementById('expense-assignment-input').value=s.options[s.selectedIndex].text.trim();document.getElementById('expense-assignment-results').classList.add('hidden')}function escapeExpense(v){const e=document.createElement('div');e.textContent=v||'';return e.innerHTML}
document.getElementById('expense-devise').onchange=e=>document.getElementById('expense-currency-label').textContent=e.target.value;function filterExpenses(){const q=document.getElementById('expense-search').value.toLowerCase().trim(),c=document.getElementById('expense-category').value,d=document.getElementById('expense-currency').value;let n=0;document.querySelectorAll('#expenses-body tr[data-search]').forEach(r=>{const show=(!q||r.dataset.search.includes(q))&&(!c||r.dataset.category===c)&&(!d||r.dataset.currency===d);r.style.display=show?'':'none';if(show)n++});document.getElementById('expense-count').textContent=n+' dépense(s)'}function openDeleteExpense(id,n){document.getElementById('delete-expense-id').value=id;document.getElementById('delete-expense-name').textContent=n;openModal('delete-expense-modal')}function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}setTimeout(()=>document.querySelector('.users-toast')?.remove(),4000);
const openExpenseModalBase=openExpenseModal;openExpenseModal=function(d=null){if(d){const category=document.getElementById('categorie_depense_id');if(!Array.from(category.options).some(o=>String(o.value)===String(d.categorie_depense_id)))category.add(new Option(d.categorie_nom,d.categorie_depense_id))}openExpenseModalBase(d)};
function switchExpenseView(view){document.querySelectorAll('.module-breadcrumbs button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('view-expenses').classList.toggle('hidden',view!=='expenses');document.getElementById('view-categories').classList.toggle('hidden',view!=='categories')}
function openCategoryModal(c=null){document.getElementById('category-action').value=c?'category_update':'category_create';document.getElementById('category-id').value=c?.id||'';document.getElementById('category-name').value=c?.nom||'';document.getElementById('category-type').value=c?.type_depense||'non_participatif';document.getElementById('category-active').value=c?.actif??1;document.getElementById('category-status-field').classList.toggle('hidden',!c);document.getElementById('category-title').textContent=c?'Modifier la catégorie':'Nouvelle catégorie';openModal('category-modal')}function filterCategories(){const q=document.getElementById('category-search').value.toLowerCase().trim();let n=0;document.querySelectorAll('#categories-body tr[data-search]').forEach(r=>{const show=!q||r.dataset.search.includes(q);r.style.display=show?'':'none';if(show)n++});document.getElementById('category-count').textContent=n+' catégorie(s)'}function toggleCategory(id,name,active){document.getElementById('toggle-category-id').value=id;document.getElementById('toggle-category-title').textContent=active?'Désactiver cette catégorie ?':'Réactiver cette catégorie ?';document.getElementById('toggle-category-name').textContent=name;document.getElementById('toggle-category-button').textContent=active?'Désactiver':'Réactiver';openModal('toggle-category-modal')}
</script></body></html>
